#!/usr/bin/env python3
"""
Round 173b (culprits-tiles-more), 4 October 2026. Upload after round172b_tiles.py.

The two Global Soil Biodiversity Atlas maps as picture tiles (tiles/esdac_*),
scripts/wba_nature.py (WBA Nature Benchmark), and forest500_map.py as in
round 172b (wba_nature uses its capitals). Whole files, each written only if
it differs. Run from the repository root.
"""
import base64, pathlib

FILES = {
    "tiles/esdac_soil_biodiversity.build.json": "",
    "tiles/esdac_soil_biodiversity.choices.json": "",
    "tiles/esdac_soil_biodiversity.pmtiles": "",
    "tiles/esdac_soil_threats.build.json": "",
    "tiles/esdac_soil_threats.choices.json": "",
    "tiles/esdac_soil_threats.pmtiles": "",
    "scripts/wba_nature.py": "",
    "scripts/forest500_map.py": "",
}


def main():
    for name, data in FILES.items():
        p = pathlib.Path(name)
        new = base64.b64decode(data)
        if p.exists() and p.read_bytes() == new:
            print(f"round173b_tiles: {name} already up to date")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(new)
        print(f"round173b_tiles: wrote {name}")


if __name__ == "__main__":
    main()
